INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-001','Phân biệt == và equals trong Java. Khi so sánh String nên dùng gì?','Phân biệt == và equals trong Java. Khi so sánh String nên dùng gì?','Java','Easy','KNOWLEDGE','Với object, == so sánh hai tham chiếu có trỏ cùng đối tượng hay không. equals có thể được override để so sánh giá trị logic; String.equals so sánh nội dung chuỗi. Dùng Objects.equals(a,b) để so sánh an toàn khi có null.','Java','Intern','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Với object, == so sánh hai tham chiếu có trỏ cùng đối tượng hay không.','Với object, == so sánh hai tham chiếu có trỏ cùng đối tượng hay không.','4.0','0.4','["tham chiếu", "cùng đối tượng", "reference"]','["Với object, == so sánh hai tham chiếu có trỏ cùng đối tượng hay không.", "Hai biến object dùng == để kiểm tra cùng địa chỉ tham chiếu."]','["== luôn so sánh nội dung của mọi object."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'equals có thể được override để so sánh giá trị logic; String.equals so sánh nội dung chuỗi.','equals có thể được override để so sánh giá trị logic; String.equals so sánh nội dung chuỗi.','3.5','0.35','["equals", "nội dung", "override"]','["equals có thể được override để so sánh giá trị logic; String.equals so sánh nội dung chuỗi.", "So nội dung hai chuỗi bằng String.equals thay vì so địa chỉ."]','["String.equals chỉ so sánh địa chỉ bộ nhớ."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng Objects.equals(a,b) để so sánh an toàn khi có null.','Dùng Objects.equals(a,b) để so sánh an toàn khi có null.','2.5','0.25','["Objects.equals", "null", "an toàn"]','["Dùng Objects.equals(a,b) để so sánh an toàn khi có null.", "Objects.equals xử lý được trường hợp một chuỗi là null."]','["Gọi a.equals(b) luôn an toàn dù a là null."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-002','Khi dùng HashMap với key là object tự định nghĩa, cần chú ý equals và hashCode thế nào?','Khi dùng HashMap với key là object tự định nghĩa, cần chú ý equals và hashCode thế nào?','Java','Medium','APPLICATION','Hai object equals nhau phải có cùng hashCode. HashMap dùng hashCode chọn bucket rồi equals để phân biệt key trong bucket. Tránh thay đổi các trường tham gia equals và hashCode sau khi key đã được đưa vào map.','Java','Junior','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Hai object equals nhau phải có cùng hashCode.','Hai object equals nhau phải có cùng hashCode.','4.0','0.4','["equals", "hashCode", "cùng"]','["Hai object equals nhau phải có cùng hashCode.", "Nếu equals trả true thì mã băm của hai key phải giống nhau."]','["Hai object equals nhau được phép có hashCode khác nhau."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'HashMap dùng hashCode chọn bucket rồi equals để phân biệt key trong bucket.','HashMap dùng hashCode chọn bucket rồi equals để phân biệt key trong bucket.','3.5','0.35','["bucket", "va chạm", "equals"]','["HashMap dùng hashCode chọn bucket rồi equals để phân biệt key trong bucket.", "Mã băm chọn nhóm lưu trữ, còn equals xác định đúng khóa khi va chạm."]','["Chỉ cần hashCode giống nhau là HashMap coi hai key bằng nhau."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Tránh thay đổi các trường tham gia equals và hashCode sau khi key đã được đưa vào map.','Tránh thay đổi các trường tham gia equals và hashCode sau khi key đã được đưa vào map.','2.5','0.25','["bất biến", "thay đổi", "tra cứu"]','["Tránh thay đổi các trường tham gia equals và hashCode sau khi key đã được đưa vào map.", "Nên dùng key bất biến để không làm mất khả năng tìm kiếm sau khi chèn."]','["Thay đổi key trong map không bao giờ ảnh hưởng việc tra cứu."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-003','Một bộ đếm dùng chung giữa nhiều thread bị sai số. Bạn phân tích và sửa thế nào?','Một bộ đếm dùng chung giữa nhiều thread bị sai số. Bạn phân tích và sửa thế nào?','Java','Hard','SCENARIO','Phép tăng count++ gồm nhiều thao tác nên có thể xảy ra race condition. Dùng AtomicInteger hoặc synchronized phù hợp để bảo vệ thao tác cập nhật. Đo tải và kiểm thử đồng thời; cân nhắc LongAdder khi tranh chấp cao.','Java','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Phép tăng count++ gồm nhiều thao tác nên có thể xảy ra race condition.','Phép tăng count++ gồm nhiều thao tác nên có thể xảy ra race condition.','4.0','0.4','["race condition", "nguyên tử", "nhiều thao tác"]','["Phép tăng count++ gồm nhiều thao tác nên có thể xảy ra race condition.", "Đọc, cộng rồi ghi không phải một thao tác nguyên tử khi nhiều luồng chạy."]','["count++ luôn là thao tác nguyên tử trong Java."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng AtomicInteger hoặc synchronized phù hợp để bảo vệ thao tác cập nhật.','Dùng AtomicInteger hoặc synchronized phù hợp để bảo vệ thao tác cập nhật.','3.5','0.35','["AtomicInteger", "synchronized", "khóa"]','["Dùng AtomicInteger hoặc synchronized phù hợp để bảo vệ thao tác cập nhật.", "Có thể dùng compare-and-set qua AtomicInteger hoặc khóa đồng bộ."]','["Chỉ thêm volatile là đủ để count++ luôn chính xác."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Đo tải và kiểm thử đồng thời; cân nhắc LongAdder khi tranh chấp cao.','Đo tải và kiểm thử đồng thời; cân nhắc LongAdder khi tranh chấp cao.','2.5','0.25','["kiểm thử", "LongAdder", "tranh chấp"]','["Đo tải và kiểm thử đồng thời; cân nhắc LongAdder khi tranh chấp cao.", "Cần stress test nhiều luồng và đo contention trước khi chọn cách tối ưu."]','["Không cần kiểm thử đồng thời sau khi thêm khóa."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-004','Spring Boot giúp khởi tạo ứng dụng Spring như thế nào?','Spring Boot giúp khởi tạo ứng dụng Spring như thế nào?','Spring Boot','Easy','KNOWLEDGE','Spring Boot được xây trên Spring Framework, không thay thế cơ chế IoC của Spring. Auto-configuration cấu hình theo classpath và điều kiện, có thể bị cấu hình người dùng thay thế. Starter gom dependency; embedded server giúp đóng gói ứng dụng chạy độc lập.','Spring Boot','Intern','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Spring Boot được xây trên Spring Framework, không thay thế cơ chế IoC của Spring.','Spring Boot được xây trên Spring Framework, không thay thế cơ chế IoC của Spring.','4.0','0.4','["Spring Framework", "IoC", "bean"]','["Spring Boot được xây trên Spring Framework, không thay thế cơ chế IoC của Spring.", "Boot bổ sung tiện ích lên nền Spring và vẫn dùng container quản lý bean."]','["Spring Boot là một ngôn ngữ lập trình độc lập."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Auto-configuration cấu hình theo classpath và điều kiện, có thể bị cấu hình người dùng thay thế.','Auto-configuration cấu hình theo classpath và điều kiện, có thể bị cấu hình người dùng thay thế.','3.5','0.35','["auto-configuration", "điều kiện", "classpath"]','["Auto-configuration cấu hình theo classpath và điều kiện, có thể bị cấu hình người dùng thay thế.", "Boot tự cấu hình có điều kiện dựa vào dependency và cấu hình hiện có."]','["Auto-configuration luôn ghi đè mọi cấu hình người dùng."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Starter gom dependency; embedded server giúp đóng gói ứng dụng chạy độc lập.','Starter gom dependency; embedded server giúp đóng gói ứng dụng chạy độc lập.','2.5','0.25','["starter", "embedded", "Tomcat"]','["Starter gom dependency; embedded server giúp đóng gói ứng dụng chạy độc lập.", "Starter giảm việc khai báo thư viện và Tomcat nhúng giúp chạy bằng java -jar."]','["Mọi ứng dụng Spring Boot bắt buộc phải triển khai lên Tomcat bên ngoài."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-005','Vì sao nên dùng constructor injection cho dependency bắt buộc?','Vì sao nên dùng constructor injection cho dependency bắt buộc?','Spring Boot','Medium','APPLICATION','Dependency được khai báo rõ trong constructor và có thể giữ trong trường final. Có thể truyền mock trực tiếp khi unit test mà không cần dựng Spring context. Vòng phụ thuộc constructor cần được xử lý bằng cách xem lại thiết kế.','Spring Boot','Junior','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dependency được khai báo rõ trong constructor và có thể giữ trong trường final.','Dependency được khai báo rõ trong constructor và có thể giữ trong trường final.','4.0','0.4','["constructor", "final", "bắt buộc"]','["Dependency được khai báo rõ trong constructor và có thể giữ trong trường final.", "Hàm khởi tạo thể hiện rõ thành phần bắt buộc, hỗ trợ tính bất biến."]','["Constructor injection bắt buộc dependency phải được tạo bằng new trong service."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Có thể truyền mock trực tiếp khi unit test mà không cần dựng Spring context.','Có thể truyền mock trực tiếp khi unit test mà không cần dựng Spring context.','3.5','0.35','["mock", "unit test", "kiểm thử"]','["Có thể truyền mock trực tiếp khi unit test mà không cần dựng Spring context.", "Kiểm thử đơn vị chỉ cần khởi tạo service với dependency giả lập."]','["Constructor injection khiến không thể dùng mock trong unit test."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Vòng phụ thuộc constructor cần được xử lý bằng cách xem lại thiết kế.','Vòng phụ thuộc constructor cần được xử lý bằng cách xem lại thiết kế.','2.5','0.25','["vòng phụ thuộc", "thiết kế", "tách"]','["Vòng phụ thuộc constructor cần được xử lý bằng cách xem lại thiết kế.", "Nếu hai service đòi nhau ở hàm tạo thì nên tách trách nhiệm để bỏ vòng phụ thuộc."]','["Vòng phụ thuộc constructor luôn được Spring tự giải quyết."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-006','Một phương thức @Transactional gọi nội bộ phương thức khác nhưng rollback không như mong đợi. Bạn kiểm tra gì?','Một phương thức @Transactional gọi nội bộ phương thức khác nhưng rollback không như mong đợi. Bạn kiểm tra gì?','Spring Boot','Hard','SCENARIO','Proxy-based AOP không chặn self-invocation qua this nên annotation ở lời gọi nội bộ có thể không có hiệu lực. Kiểm tra loại exception và rollbackFor vì checked exception mặc định không gây rollback. Kiểm thử tích hợp trạng thái database và cân nhắc tách lời gọi sang bean khác.','Spring Boot','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Proxy-based AOP không chặn self-invocation qua this nên annotation ở lời gọi nội bộ có thể không có hiệu lực.','Proxy-based AOP không chặn self-invocation qua this nên annotation ở lời gọi nội bộ có thể không có hiệu lực.','4.0','0.4','["proxy", "self-invocation", "cùng đối tượng"]','["Proxy-based AOP không chặn self-invocation qua this nên annotation ở lời gọi nội bộ có thể không có hiệu lực.", "Gọi trong cùng đối tượng có thể bỏ qua proxy giao dịch của Spring."]','["Mọi self-invocation đều đi qua proxy @Transactional."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Kiểm tra loại exception và rollbackFor vì checked exception mặc định không gây rollback.','Kiểm tra loại exception và rollbackFor vì checked exception mặc định không gây rollback.','3.5','0.35','["checked", "rollbackFor", "exception"]','["Kiểm tra loại exception và rollbackFor vì checked exception mặc định không gây rollback.", "Cần xem exception là checked hay runtime và quy tắc rollback đã cấu hình."]','["Mọi checked exception đều tự động rollback theo mặc định."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Kiểm thử tích hợp trạng thái database và cân nhắc tách lời gọi sang bean khác.','Kiểm thử tích hợp trạng thái database và cân nhắc tách lời gọi sang bean khác.','2.5','0.25','["kiểm thử", "database", "bean khác"]','["Kiểm thử tích hợp trạng thái database và cân nhắc tách lời gọi sang bean khác.", "Xác minh dữ liệu sau lỗi và đưa ranh giới giao dịch qua một bean phù hợp."]','["Chỉ xem log là đủ để khẳng định transaction đã rollback."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-007','INNER JOIN và LEFT JOIN khác nhau thế nào?','INNER JOIN và LEFT JOIN khác nhau thế nào?','SQL','Easy','KNOWLEDGE','INNER JOIN chỉ giữ các cặp dòng thỏa điều kiện nối ở cả hai bảng. LEFT JOIN giữ mọi dòng bảng trái; cột phía phải là NULL khi không có dòng khớp. Điều kiện WHERE trên cột bảng phải có thể loại dòng NULL và thay đổi ý nghĩa LEFT JOIN.','SQL','Intern','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'INNER JOIN chỉ giữ các cặp dòng thỏa điều kiện nối ở cả hai bảng.','INNER JOIN chỉ giữ các cặp dòng thỏa điều kiện nối ở cả hai bảng.','4.0','0.4','["INNER JOIN", "khớp", "cả hai"]','["INNER JOIN chỉ giữ các cặp dòng thỏa điều kiện nối ở cả hai bảng.", "Nối trong chỉ trả các bản ghi có đối tác khớp."]','["INNER JOIN luôn giữ toàn bộ dòng bảng trái."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'LEFT JOIN giữ mọi dòng bảng trái; cột phía phải là NULL khi không có dòng khớp.','LEFT JOIN giữ mọi dòng bảng trái; cột phía phải là NULL khi không có dòng khớp.','3.5','0.35','["LEFT JOIN", "NULL", "bảng trái"]','["LEFT JOIN giữ mọi dòng bảng trái; cột phía phải là NULL khi không có dòng khớp.", "Nối trái vẫn giữ bản ghi không tìm được đối tác và điền NULL ở bên phải."]','["LEFT JOIN loại bỏ mọi dòng không có bản ghi phía phải."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Điều kiện WHERE trên cột bảng phải có thể loại dòng NULL và thay đổi ý nghĩa LEFT JOIN.','Điều kiện WHERE trên cột bảng phải có thể loại dòng NULL và thay đổi ý nghĩa LEFT JOIN.','2.5','0.25','["WHERE", "ON", "điều kiện"]','["Điều kiện WHERE trên cột bảng phải có thể loại dòng NULL và thay đổi ý nghĩa LEFT JOIN.", "Đặt lọc bên phải trong WHERE cần cẩn thận vì có thể làm mất các dòng chưa khớp."]','["Đặt điều kiện bên phải ở WHERE hay ON luôn cho cùng kết quả."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-008','Khi nào nên tạo index và làm sao kiểm tra index có hữu ích?','Khi nào nên tạo index và làm sao kiểm tra index có hữu ích?','SQL','Medium','APPLICATION','Xem các cột thường lọc WHERE, nối JOIN hoặc sắp xếp để chọn index phù hợp. Index tốn dung lượng và làm tăng chi phí INSERT UPDATE DELETE. Dùng EXPLAIN và đo thời gian trước sau trên dữ liệu đại diện.','SQL','Junior','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Xem các cột thường lọc WHERE, nối JOIN hoặc sắp xếp để chọn index phù hợp.','Xem các cột thường lọc WHERE, nối JOIN hoặc sắp xếp để chọn index phù hợp.','4.0','0.4','["WHERE", "JOIN", "truy vấn"]','["Xem các cột thường lọc WHERE, nối JOIN hoặc sắp xếp để chọn index phù hợp.", "Tạo chỉ mục theo mẫu truy vấn thực tế, nhất là điều kiện tìm kiếm và liên kết."]','["Nên tạo index cho mọi cột bất kể truy vấn."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Index tốn dung lượng và làm tăng chi phí INSERT UPDATE DELETE.','Index tốn dung lượng và làm tăng chi phí INSERT UPDATE DELETE.','3.5','0.35','["dung lượng", "ghi", "UPDATE"]','["Index tốn dung lượng và làm tăng chi phí INSERT UPDATE DELETE.", "Chỉ mục tăng tốc đọc nhưng phải đánh đổi bộ nhớ và công cập nhật khi ghi."]','["Index luôn tăng tốc cả đọc và ghi mà không tốn dung lượng."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng EXPLAIN và đo thời gian trước sau trên dữ liệu đại diện.','Dùng EXPLAIN và đo thời gian trước sau trên dữ liệu đại diện.','2.5','0.25','["EXPLAIN", "đo", "plan"]','["Dùng EXPLAIN và đo thời gian trước sau trên dữ liệu đại diện.", "Kiểm tra execution plan và benchmark thay vì đoán index đã được dùng."]','["Có index thì không cần xem execution plan hay đo lại."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-009','Hai yêu cầu đặt hàng đồng thời có thể bán vượt tồn kho. Bạn xử lý ở database thế nào?','Hai yêu cầu đặt hàng đồng thời có thể bán vượt tồn kho. Bạn xử lý ở database thế nào?','SQL','Hard','SCENARIO','Cần giữ thao tác kiểm tra và trừ tồn kho trong cùng ranh giới transaction. Dùng UPDATE có điều kiện stock >= quantity và kiểm tra số dòng cập nhật hoặc khóa dòng phù hợp. Xử lý retry có giới hạn cho deadlock và kiểm tra tính idempotent khi gửi lại yêu cầu.','SQL','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Cần giữ thao tác kiểm tra và trừ tồn kho trong cùng ranh giới transaction.','Cần giữ thao tác kiểm tra và trừ tồn kho trong cùng ranh giới transaction.','4.0','0.4','["transaction", "đồng thời", "kiểm tra"]','["Cần giữ thao tác kiểm tra và trừ tồn kho trong cùng ranh giới transaction.", "Đọc lượng tồn rồi cập nhật riêng rẽ có thể tạo race condition nên cần giao dịch nhất quán."]','["Chỉ kiểm tra tồn kho ở giao diện là đủ để tránh bán vượt."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng UPDATE có điều kiện stock >= quantity và kiểm tra số dòng cập nhật hoặc khóa dòng phù hợp.','Dùng UPDATE có điều kiện stock >= quantity và kiểm tra số dòng cập nhật hoặc khóa dòng phù hợp.','3.5','0.35','["UPDATE", "điều kiện", "khóa"]','["Dùng UPDATE có điều kiện stock >= quantity và kiểm tra số dòng cập nhật hoặc khóa dòng phù hợp.", "Có thể cập nhật nguyên tử kèm điều kiện số lượng thay vì đọc rồi ghi không bảo vệ."]','["Luôn đọc stock bằng SELECT thường rồi UPDATE là an toàn với mọi mức cô lập."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Xử lý retry có giới hạn cho deadlock và kiểm tra tính idempotent khi gửi lại yêu cầu.','Xử lý retry có giới hạn cho deadlock và kiểm tra tính idempotent khi gửi lại yêu cầu.','2.5','0.25','["deadlock", "retry", "idempotent"]','["Xử lý retry có giới hạn cho deadlock và kiểm tra tính idempotent khi gửi lại yêu cầu.", "Khi có bế tắc cần retry có kiểm soát và tránh trừ kho hai lần cho một yêu cầu."]','["Retry vô hạn không cần idempotency là cách xử lý deadlock tốt nhất."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-010','Phân biệt GET, POST, PUT và DELETE trong API HTTP.','Phân biệt GET, POST, PUT và DELETE trong API HTTP.','REST API','Easy','KNOWLEDGE','GET dùng đọc tài nguyên và không nên tạo tác dụng phụ thay đổi dữ liệu nghiệp vụ. POST thường tạo hoặc xử lý yêu cầu; PUT thường thay thế trạng thái tại URI xác định. PUT và DELETE có ngữ nghĩa idempotent; phản hồi HTTP có thể khác giữa các lần gọi.','REST API','Intern','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'GET dùng đọc tài nguyên và không nên tạo tác dụng phụ thay đổi dữ liệu nghiệp vụ.','GET dùng đọc tài nguyên và không nên tạo tác dụng phụ thay đổi dữ liệu nghiệp vụ.','4.0','0.4','["GET", "đọc", "an toàn"]','["GET dùng đọc tài nguyên và không nên tạo tác dụng phụ thay đổi dữ liệu nghiệp vụ.", "Yêu cầu lấy dữ liệu cần giữ tính an toàn, không dùng GET để xóa bản ghi."]','["GET nên được dùng để xóa hoặc tạo dữ liệu."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'POST thường tạo hoặc xử lý yêu cầu; PUT thường thay thế trạng thái tại URI xác định.','POST thường tạo hoặc xử lý yêu cầu; PUT thường thay thế trạng thái tại URI xác định.','3.5','0.35','["POST", "PUT", "tài nguyên"]','["POST thường tạo hoặc xử lý yêu cầu; PUT thường thay thế trạng thái tại URI xác định.", "POST gửi thao tác còn PUT ghi trạng thái của tài nguyên có địa chỉ đã biết."]','["PUT chỉ được dùng để đọc dữ liệu."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'PUT và DELETE có ngữ nghĩa idempotent; phản hồi HTTP có thể khác giữa các lần gọi.','PUT và DELETE có ngữ nghĩa idempotent; phản hồi HTTP có thể khác giữa các lần gọi.','2.5','0.25','["idempotent", "DELETE", "tác động"]','["PUT và DELETE có ngữ nghĩa idempotent; phản hồi HTTP có thể khác giữa các lần gọi.", "Gọi lặp PUT hoặc DELETE phải giữ cùng tác động cuối, không bắt buộc mã trả về giống nhau."]','["Idempotent có nghĩa mọi lần gọi phải trả cùng mã HTTP."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-011','Bạn thiết kế API tạo đơn hàng với validation và phản hồi lỗi thế nào?','Bạn thiết kế API tạo đơn hàng với validation và phản hồi lỗi thế nào?','REST API','Medium','APPLICATION','Kiểm tra kiểu dữ liệu, số lượng và ràng buộc nghiệp vụ phía server. Dùng mã HTTP phù hợp và cấu trúc lỗi nhất quán có thông tin trường sai. Bảo vệ retry tạo đơn bằng idempotency key hoặc khóa nghiệp vụ duy nhất.','REST API','Junior','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Kiểm tra kiểu dữ liệu, số lượng và ràng buộc nghiệp vụ phía server.','Kiểm tra kiểu dữ liệu, số lượng và ràng buộc nghiệp vụ phía server.','4.0','0.4','["server", "validation", "nghiệp vụ"]','["Kiểm tra kiểu dữ liệu, số lượng và ràng buộc nghiệp vụ phía server.", "Không tin validation frontend; server cần xác minh đầu vào và điều kiện nghiệp vụ."]','["Chỉ cần validation phía frontend vì người dùng không thể bỏ qua."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng mã HTTP phù hợp và cấu trúc lỗi nhất quán có thông tin trường sai.','Dùng mã HTTP phù hợp và cấu trúc lỗi nhất quán có thông tin trường sai.','3.5','0.35','["HTTP", "cấu trúc", "lỗi"]','["Dùng mã HTTP phù hợp và cấu trúc lỗi nhất quán có thông tin trường sai.", "Phân biệt lỗi đầu vào với lỗi hệ thống, trả lỗi có cấu trúc để client xử lý."]','["Mọi lỗi nghiệp vụ nên trả HTTP 200 mà không có thông tin lỗi."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Bảo vệ retry tạo đơn bằng idempotency key hoặc khóa nghiệp vụ duy nhất.','Bảo vệ retry tạo đơn bằng idempotency key hoặc khóa nghiệp vụ duy nhất.','2.5','0.25','["idempotency", "retry", "duy nhất"]','["Bảo vệ retry tạo đơn bằng idempotency key hoặc khóa nghiệp vụ duy nhất.", "Một yêu cầu gửi lại không nên tạo hai đơn; có thể dùng mã chống trùng."]','["Mỗi retry luôn phải tạo thêm một đơn hàng mới."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-012','Một API phụ thuộc dịch vụ ngoài thường timeout. Bạn làm gì để tránh lỗi dây chuyền?','Một API phụ thuộc dịch vụ ngoài thường timeout. Bạn làm gì để tránh lỗi dây chuyền?','REST API','Hard','SCENARIO','Đặt timeout kết nối và đọc hữu hạn cho lời gọi ra ngoài. Chỉ retry lỗi tạm thời có backoff và giới hạn; cân nhắc idempotency. Dùng circuit breaker hoặc bulkhead, theo dõi metric và báo lỗi phụ thuộc rõ ràng.','REST API','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Đặt timeout kết nối và đọc hữu hạn cho lời gọi ra ngoài.','Đặt timeout kết nối và đọc hữu hạn cho lời gọi ra ngoài.','4.0','0.4','["timeout", "giới hạn", "kết nối"]','["Đặt timeout kết nối và đọc hữu hạn cho lời gọi ra ngoài.", "Cần giới hạn thời gian chờ để luồng xử lý không bị giữ vô hạn."]','["Không đặt timeout giúp hệ thống ổn định hơn."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Chỉ retry lỗi tạm thời có backoff và giới hạn; cân nhắc idempotency.','Chỉ retry lỗi tạm thời có backoff và giới hạn; cân nhắc idempotency.','3.5','0.35','["retry", "backoff", "idempotency"]','["Chỉ retry lỗi tạm thời có backoff và giới hạn; cân nhắc idempotency.", "Thử lại có khoảng nghỉ tăng dần, tránh retry thao tác không an toàn."]','["Retry mọi lỗi liên tục không giới hạn là cách tránh quá tải."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng circuit breaker hoặc bulkhead, theo dõi metric và báo lỗi phụ thuộc rõ ràng.','Dùng circuit breaker hoặc bulkhead, theo dõi metric và báo lỗi phụ thuộc rõ ràng.','2.5','0.25','["circuit breaker", "bulkhead", "metric"]','["Dùng circuit breaker hoặc bulkhead, theo dõi metric và báo lỗi phụ thuộc rõ ràng.", "Cô lập tài nguyên và ngắt tạm dịch vụ lỗi để bảo vệ phần còn lại."]','["Một dịch vụ lỗi nên chiếm toàn bộ thread pool của hệ thống."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-013','List và tuple trong Python khác nhau thế nào?','List và tuple trong Python khác nhau thế nào?','Python','Easy','KNOWLEDGE','List có thể thay đổi phần tử và kích thước sau khi tạo. Tuple không cho gán lại các phần tử của nó sau khi tạo. Tuple chỉ hashable nếu tất cả phần tử bên trong cũng hashable.','Python','Intern','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'List có thể thay đổi phần tử và kích thước sau khi tạo.','List có thể thay đổi phần tử và kích thước sau khi tạo.','4.0','0.4','["list", "mutable", "thay đổi"]','["List có thể thay đổi phần tử và kích thước sau khi tạo.", "Danh sách là cấu trúc mutable cho phép thêm và sửa dữ liệu."]','["List là immutable và không thể thêm phần tử."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Tuple không cho gán lại các phần tử của nó sau khi tạo.','Tuple không cho gán lại các phần tử của nó sau khi tạo.','3.5','0.35','["tuple", "bất biến", "gán lại"]','["Tuple không cho gán lại các phần tử của nó sau khi tạo.", "Bộ tuple giữ cấu trúc phần tử bất biến ở cấp container."]','["Tuple cho phép gán lại từng phần tử bằng chỉ số."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Tuple chỉ hashable nếu tất cả phần tử bên trong cũng hashable.','Tuple chỉ hashable nếu tất cả phần tử bên trong cũng hashable.','2.5','0.25','["hashable", "key", "phần tử"]','["Tuple chỉ hashable nếu tất cả phần tử bên trong cũng hashable.", "Không phải tuple nào cũng làm key dictionary được; tuple chứa list không hash được."]','["Mọi tuple đều hashable kể cả tuple chứa list."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-014','Vì sao đối số mặc định là list có thể gây lỗi? Bạn sửa thế nào?','Vì sao đối số mặc định là list có thể gây lỗi? Bạn sửa thế nào?','Python','Medium','APPLICATION','Giá trị mặc định được tạo khi định nghĩa hàm và có thể được dùng lại giữa các lời gọi. Sửa bằng mặc định None rồi tạo list mới bên trong khi chưa có giá trị. Viết test nhiều lần gọi để kiểm tra dữ liệu không rò từ lần trước.','Python','Junior','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Giá trị mặc định được tạo khi định nghĩa hàm và có thể được dùng lại giữa các lời gọi.','Giá trị mặc định được tạo khi định nghĩa hàm và có thể được dùng lại giữa các lời gọi.','4.0','0.4','["mặc định", "dùng chung", "định nghĩa"]','["Giá trị mặc định được tạo khi định nghĩa hàm và có thể được dùng lại giữa các lời gọi.", "List mặc định là một đối tượng dùng chung, không tự tạo mới mỗi lần gọi."]','["Python luôn tạo list mặc định mới cho từng lời gọi."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Sửa bằng mặc định None rồi tạo list mới bên trong khi chưa có giá trị.','Sửa bằng mặc định None rồi tạo list mới bên trong khi chưa có giá trị.','3.5','0.35','["None", "list mới", "bên trong"]','["Sửa bằng mặc định None rồi tạo list mới bên trong khi chưa có giá trị.", "Dùng sentinel như None và khởi tạo danh sách trong thân hàm."]','["Thay list mặc định bằng một list rỗng khác trong chữ ký luôn giải quyết được lỗi."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Viết test nhiều lần gọi để kiểm tra dữ liệu không rò từ lần trước.','Viết test nhiều lần gọi để kiểm tra dữ liệu không rò từ lần trước.','2.5','0.25','["test", "nhiều lần", "độc lập"]','["Viết test nhiều lần gọi để kiểm tra dữ liệu không rò từ lần trước.", "Kiểm thử hai lần gọi độc lập giúp phát hiện trạng thái bị chia sẻ ngoài ý muốn."]','["Chỉ test một lần gọi là đủ để phát hiện mọi lỗi mặc định mutable."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-015','Một tác vụ Python xử lý CPU chậm: nên dùng thread hay process?','Một tác vụ Python xử lý CPU chậm: nên dùng thread hay process?','Python','Hard','SCENARIO','Trong CPython có GIL truyền thống, thread Python không tự tăng tốc mã Python CPU-bound. Cân nhắc multiprocessing hoặc thư viện native giải phóng GIL cho phần CPU nặng. Profile trước và đo chi phí truyền dữ liệu, bộ nhớ để chọn phương án.','Python','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Trong CPython có GIL truyền thống, thread Python không tự tăng tốc mã Python CPU-bound.','Trong CPython có GIL truyền thống, thread Python không tự tăng tốc mã Python CPU-bound.','4.0','0.4','["GIL", "CPU-bound", "thread"]','["Trong CPython có GIL truyền thống, thread Python không tự tăng tốc mã Python CPU-bound.", "Nhiều luồng không bảo đảm song song CPU cho bytecode khi GIL còn bật."]','["GIL giúp mọi thread Python luôn chạy CPU song song hoàn toàn."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Cân nhắc multiprocessing hoặc thư viện native giải phóng GIL cho phần CPU nặng.','Cân nhắc multiprocessing hoặc thư viện native giải phóng GIL cho phần CPU nặng.','3.5','0.35','["multiprocessing", "native", "tiến trình"]','["Cân nhắc multiprocessing hoặc thư viện native giải phóng GIL cho phần CPU nặng.", "Có thể chia việc sang nhiều tiến trình hoặc dùng phép toán native phù hợp."]','["Multiprocessing luôn dùng chung mọi object mà không có chi phí trao đổi."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Profile trước và đo chi phí truyền dữ liệu, bộ nhớ để chọn phương án.','Profile trước và đo chi phí truyền dữ liệu, bộ nhớ để chọn phương án.','2.5','0.25','["profile", "bộ nhớ", "chi phí"]','["Profile trước và đo chi phí truyền dữ liệu, bộ nhớ để chọn phương án.", "Đo điểm nghẽn và overhead liên tiến trình thay vì chỉ tăng số worker."]','["Tăng worker vô hạn luôn tăng hiệu năng tuyến tính."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-016','Props và state khác nhau thế nào trong React?','Props và state khác nhau thế nào trong React?','React','Easy','KNOWLEDGE','Props là dữ liệu truyền từ component cha và được xem là chỉ đọc trong component nhận. State là dữ liệu component quản lý và cập nhật qua setter hoặc reducer. Thay đổi props hoặc state có thể khiến React render lại giao diện.','React','Intern','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Props là dữ liệu truyền từ component cha và được xem là chỉ đọc trong component nhận.','Props là dữ liệu truyền từ component cha và được xem là chỉ đọc trong component nhận.','4.0','0.4','["props", "cha", "chỉ đọc"]','["Props là dữ liệu truyền từ component cha và được xem là chỉ đọc trong component nhận.", "Component con nhận đầu vào từ cha và không tự sửa trực tiếp props."]','["Component con nên sửa trực tiếp props để cập nhật cha."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'State là dữ liệu component quản lý và cập nhật qua setter hoặc reducer.','State là dữ liệu component quản lý và cập nhật qua setter hoặc reducer.','3.5','0.35','["state", "setter", "reducer"]','["State là dữ liệu component quản lý và cập nhật qua setter hoặc reducer.", "Trạng thái nội bộ cần thay đổi bằng API cập nhật state của React."]','["Nên sửa trực tiếp object state mà không gọi setter."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Thay đổi props hoặc state có thể khiến React render lại giao diện.','Thay đổi props hoặc state có thể khiến React render lại giao diện.','2.5','0.25','["render", "giao diện", "thay đổi"]','["Thay đổi props hoặc state có thể khiến React render lại giao diện.", "React dựng lại UI theo dữ liệu mới khi trạng thái hoặc đầu vào đổi."]','["Thay đổi state không bao giờ làm component render lại."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-017','Khi fetch dữ liệu trong useEffect, bạn tránh race condition thế nào?','Khi fetch dữ liệu trong useEffect, bạn tránh race condition thế nào?','React','Medium','APPLICATION','Khai báo dependency đúng để effect phản ánh giá trị dùng trong lời gọi. Hủy request bằng AbortController hoặc bỏ qua response cũ sau cleanup. Hiển thị trạng thái loading và xử lý lỗi để UI không treo hoặc báo thành công giả.','React','Junior','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Khai báo dependency đúng để effect phản ánh giá trị dùng trong lời gọi.','Khai báo dependency đúng để effect phản ánh giá trị dùng trong lời gọi.','4.0','0.4','["dependency", "effect", "phụ thuộc"]','["Khai báo dependency đúng để effect phản ánh giá trị dùng trong lời gọi.", "Danh sách phụ thuộc phải khớp dữ liệu mà effect sử dụng."]','["Luôn để dependency rỗng dù effect dùng biến thay đổi."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Hủy request bằng AbortController hoặc bỏ qua response cũ sau cleanup.','Hủy request bằng AbortController hoặc bỏ qua response cũ sau cleanup.','3.5','0.35','["AbortController", "cleanup", "response cũ"]','["Hủy request bằng AbortController hoặc bỏ qua response cũ sau cleanup.", "Cần ngăn kết quả của yêu cầu cũ ghi đè kết quả mới khi component đổi."]','["Response đến sau luôn phải ghi đè dữ liệu bất kể request nào mới."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Hiển thị trạng thái loading và xử lý lỗi để UI không treo hoặc báo thành công giả.','Hiển thị trạng thái loading và xử lý lỗi để UI không treo hoặc báo thành công giả.','2.5','0.25','["loading", "lỗi", "UI"]','["Hiển thị trạng thái loading và xử lý lỗi để UI không treo hoặc báo thành công giả.", "UI cần phản ánh đang tải, thất bại và cho phép thử lại hợp lý."]','["Có thể bỏ qua mọi lỗi fetch mà vẫn báo thành công."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-018','Danh sách lớn render chậm. Bạn phân tích và tối ưu React thế nào?','Danh sách lớn render chậm. Bạn phân tích và tối ưu React thế nào?','React','Hard','SCENARIO','Dùng React Profiler để xác định component render tốn thời gian. Dùng key ổn định và cân nhắc virtualization cho danh sách dài. Chỉ dùng memoization khi có lợi và kiểm tra dependency cùng tính đúng đắn.','React','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng React Profiler để xác định component render tốn thời gian.','Dùng React Profiler để xác định component render tốn thời gian.','4.0','0.4','["Profiler", "đo", "render"]','["Dùng React Profiler để xác định component render tốn thời gian.", "Cần đo lại số lần render và phần chậm trước khi thêm tối ưu."]','["Luôn thêm useMemo cho mọi biểu thức mà không cần đo."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng key ổn định và cân nhắc virtualization cho danh sách dài.','Dùng key ổn định và cân nhắc virtualization cho danh sách dài.','3.5','0.35','["key", "virtualization", "danh sách"]','["Dùng key ổn định và cân nhắc virtualization cho danh sách dài.", "Chỉ render phần danh sách nhìn thấy và giữ định danh item ổn định."]','["Dùng index làm key luôn đúng cả khi danh sách sắp xếp lại."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Chỉ dùng memoization khi có lợi và kiểm tra dependency cùng tính đúng đắn.','Chỉ dùng memoization khi có lợi và kiểm tra dependency cùng tính đúng đắn.','2.5','0.25','["memo", "dependency", "đúng"]','["Chỉ dùng memoization khi có lợi và kiểm tra dependency cùng tính đúng đắn.", "Memo cần giữ kết quả đúng và phải được chứng minh giảm chi phí thực tế."]','["Memoization không có chi phí và không thể gây dữ liệu cũ."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-019','Image, container và volume trong Docker khác nhau thế nào?','Image, container và volume trong Docker khác nhau thế nào?','Docker','Easy','KNOWLEDGE','Image là mẫu filesystem và cấu hình dùng tạo container. Container là instance chạy từ image và có lớp ghi riêng. Volume lưu dữ liệu cần tồn tại ngoài vòng đời container.','Docker','Intern','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Image là mẫu filesystem và cấu hình dùng tạo container.','Image là mẫu filesystem và cấu hình dùng tạo container.','4.0','0.4','["image", "mẫu", "container"]','["Image là mẫu filesystem và cấu hình dùng tạo container.", "Ảnh container là bản mẫu để khởi tạo tiến trình có môi trường xác định."]','["Image là một tiến trình đang chạy trên máy."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Container là instance chạy từ image và có lớp ghi riêng.','Container là instance chạy từ image và có lớp ghi riêng.','3.5','0.35','["container", "instance", "lớp ghi"]','["Container là instance chạy từ image và có lớp ghi riêng.", "Container là thực thể được tạo từ image với vòng đời riêng."]','["Xóa container luôn xóa toàn bộ dữ liệu của mọi volume."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Volume lưu dữ liệu cần tồn tại ngoài vòng đời container.','Volume lưu dữ liệu cần tồn tại ngoài vòng đời container.','2.5','0.25','["volume", "dữ liệu", "vòng đời"]','["Volume lưu dữ liệu cần tồn tại ngoài vòng đời container.", "Database nên có vùng lưu bền vững độc lập với việc tạo lại container."]','["Dữ liệu database chỉ nên lưu ở lớp ghi tạm của container."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-020','Ứng dụng trong container kết nối database khác container như thế nào?','Ứng dụng trong container kết nối database khác container như thế nào?','Docker','Medium','APPLICATION','Dùng tên service và cổng bên trong trên cùng mạng Compose. Phân biệt published port của host với port mà container lắng nghe. Chờ readiness và xử lý kết nối lỗi vì thứ tự tạo container không bảo đảm dịch vụ đã sẵn sàng.','Docker','Junior','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Dùng tên service và cổng bên trong trên cùng mạng Compose.','Dùng tên service và cổng bên trong trên cùng mạng Compose.','4.0','0.4','["service", "network", "DNS"]','["Dùng tên service và cổng bên trong trên cùng mạng Compose.", "Các container cùng network tìm nhau bằng DNS service thay vì IP cố định."]','["Container luôn dùng localhost để gọi database ở container khác."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Phân biệt published port của host với port mà container lắng nghe.','Phân biệt published port của host với port mà container lắng nghe.','3.5','0.35','["host", "port", "nội bộ"]','["Phân biệt published port của host với port mà container lắng nghe.", "Cổng host phục vụ truy cập bên ngoài, còn nội bộ dùng cổng dịch vụ."]','["Cổng host và cổng container bắt buộc luôn giống nhau."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Chờ readiness và xử lý kết nối lỗi vì thứ tự tạo container không bảo đảm dịch vụ đã sẵn sàng.','Chờ readiness và xử lý kết nối lỗi vì thứ tự tạo container không bảo đảm dịch vụ đã sẵn sàng.','2.5','0.25','["healthcheck", "readiness", "retry"]','["Chờ readiness và xử lý kết nối lỗi vì thứ tự tạo container không bảo đảm dịch vụ đã sẵn sàng.", "Cần healthcheck và retry hữu hạn thay vì chỉ dựa vào depends_on dạng đơn giản."]','["Container đã được tạo nghĩa là database đã sẵn sàng nhận truy vấn."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-021','Máy bị lag khi build và chạy nhiều model trong Docker. Bạn xử lý thế nào?','Máy bị lag khi build và chạy nhiều model trong Docker. Bạn xử lý thế nào?','Docker','Hard','SCENARIO','Đo CPU RAM swap và I/O bằng công cụ hệ thống hoặc docker stats trước. Giới hạn song song lúc build, worker và thread suy luận để tránh chiếm hết tài nguyên. Tái sử dụng image và cache model, không build lại khi chỉ cần start container.','Docker','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Đo CPU RAM swap và I/O bằng công cụ hệ thống hoặc docker stats trước.','Đo CPU RAM swap và I/O bằng công cụ hệ thống hoặc docker stats trước.','4.0','0.4','["CPU", "RAM", "swap"]','["Đo CPU RAM swap và I/O bằng công cụ hệ thống hoặc docker stats trước.", "Xác định nghẽn bộ nhớ hay tính toán bằng số đo thay vì quy hết cho Docker."]','["Di chuyển sang ổ lớn hơn luôn làm giảm mức dùng RAM của model."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Giới hạn song song lúc build, worker và thread suy luận để tránh chiếm hết tài nguyên.','Giới hạn song song lúc build, worker và thread suy luận để tránh chiếm hết tài nguyên.','3.5','0.35','["song song", "thread", "giới hạn"]','["Giới hạn song song lúc build, worker và thread suy luận để tránh chiếm hết tài nguyên.", "Giảm số tác vụ đồng thời và đặt ngân sách tài nguyên cho dịch vụ nặng."]','["Càng nhiều worker và thread luôn càng ít lag."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Tái sử dụng image và cache model, không build lại khi chỉ cần start container.','Tái sử dụng image và cache model, không build lại khi chỉ cần start container.','2.5','0.25','["cache", "build", "start"]','["Tái sử dụng image và cache model, không build lại khi chỉ cần start container.", "Tách bước build khỏi khởi động và lưu cache để tránh tải hoặc biên dịch lặp lại."]','["Mỗi lần khởi động đều bắt buộc rebuild toàn bộ image."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-022','Working tree, staging area và commit khác nhau thế nào?','Working tree, staging area và commit khác nhau thế nào?','Git','Easy','KNOWLEDGE','Working tree chứa các file đang được chỉnh sửa. Staging area chọn phiên bản thay đổi sẽ đưa vào commit tiếp theo. Commit lưu snapshot có lịch sử để có thể so sánh và truy vết.','Git','Intern','synthetic-ai-v2',10,1);
