INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-023','Bạn xử lý merge conflict mà vẫn giữ thay đổi đúng của cả hai phía như thế nào?','Bạn xử lý merge conflict mà vẫn giữ thay đổi đúng của cả hai phía như thế nào?','Git','Medium','APPLICATION','Đọc các phần xung đột và hiểu ý nghĩa thay đổi thay vì chọn một phía máy móc. Sửa nội dung, bỏ conflict markers rồi stage và hoàn thành merge. Chạy kiểm thử phần bị ảnh hưởng và kiểm tra diff trước khi chia sẻ.','Git','Junior','synthetic-ai-v2',10,1);
