INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-024','Một commit lỗi đã được nhiều người pull. Bạn rollback thế nào?','Một commit lỗi đã được nhiều người pull. Bạn rollback thế nào?','Git','Hard','SCENARIO','Ưu tiên git revert để tạo commit đảo thay đổi mà không viết lại lịch sử chung. Xác định phạm vi lỗi, dependency và kiểm thử bản hoàn tác. Trao đổi với nhóm và theo dõi triển khai sau khi hoàn tác.','Git','Middle','synthetic-ai-v2',10,1);
