INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'So sánh điểm mô hình với điểm người chấm độc lập bằng MAE và phân tích sai số.','So sánh điểm mô hình với điểm người chấm độc lập bằng MAE và phân tích sai số.','4.0','0.4','["MAE", "người chấm", "sai số"]','["So sánh điểm mô hình với điểm người chấm độc lập bằng MAE và phân tích sai số.", "Cần nhãn chuyên gia và xem độ lệch điểm chứ không chỉ xem vài ví dụ đẹp."]','["Nhãn tự sinh luôn tương đương đánh giá của chuyên gia."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Tách test theo câu hỏi để tránh câu trả lời biến thể làm rò dữ liệu.','Tách test theo câu hỏi để tránh câu trả lời biến thể làm rò dữ liệu.','3.5','0.35','["câu hỏi", "nhóm", "rò"]','["Tách test theo câu hỏi để tránh câu trả lời biến thể làm rò dữ liệu.", "Các phiên bản đáp án cho một câu cần nằm cùng nhóm khi chia tập."]','["Chia từng dòng ngẫu nhiên luôn ngăn mọi dạng rò dữ liệu."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Kiểm tra câu diễn đạt lại, phủ định, sai kiến thức và trường hợp ngoài miền.','Kiểm tra câu diễn đạt lại, phủ định, sai kiến thức và trường hợp ngoài miền.','2.5','0.25','["phủ định", "diễn đạt", "ngoài miền"]','["Kiểm tra câu diễn đạt lại, phủ định, sai kiến thức và trường hợp ngoài miền.", "Bộ thử cần có paraphrase, câu sai nhưng giống từ và chủ đề lạ."]','["Tương đồng ngữ nghĩa cao luôn chứng minh câu trả lời đúng chuyên môn."]');
INSERT INTO interview_questions (external_key,title,question_text,topic,difficulty,question_type,reference_answer,skill,seniority,source,max_score,is_active) VALUES ('m3-v2-030','Model có điểm test tổng hợp cao nhưng chấm CV hoặc phỏng vấn thật kém. Bạn làm gì?','Model có điểm test tổng hợp cao nhưng chấm CV hoặc phỏng vấn thật kém. Bạn làm gì?','Machine Learning','Hard','SCENARIO','Kiểm tra domain shift và dữ liệu rò giữa train với test. Thu thập mẫu thật có nhãn độc lập và đánh giá theo từng nhóm lỗi. So sánh baseline, hiệu chỉnh ngưỡng trên validation và giữ test cuối độc lập.','Machine Learning','Middle','synthetic-ai-v2',10,1);
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Kiểm tra domain shift và dữ liệu rò giữa train với test.','Kiểm tra domain shift và dữ liệu rò giữa train với test.','4.0','0.4','["domain shift", "dữ liệu", "rò"]','["Kiểm tra domain shift và dữ liệu rò giữa train với test.", "Cần xem dữ liệu thật khác mẫu tổng hợp ở ngôn ngữ, bố cục hay phân phối ra sao."]','["Điểm cao trên dữ liệu tổng hợp bảo đảm chất lượng trên người dùng thật."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'Thu thập mẫu thật có nhãn độc lập và đánh giá theo từng nhóm lỗi.','Thu thập mẫu thật có nhãn độc lập và đánh giá theo từng nhóm lỗi.','3.5','0.35','["nhãn", "thật", "lỗi"]','["Thu thập mẫu thật có nhãn độc lập và đánh giá theo từng nhóm lỗi.", "Cần bộ đánh giá đại diện cùng phân tích theo trường, chủ đề hoặc cấp độ."]','["Chỉ tăng số mẫu tổng hợp giống nhau sẽ sửa mọi lỗi thực tế."]');
INSERT INTO evaluation_rubrics (question_id,criterion_name,criterion_description,max_score,weight,expected_keywords,reference_answers,misconceptions) VALUES (@question_id,'So sánh baseline, hiệu chỉnh ngưỡng trên validation và giữ test cuối độc lập.','So sánh baseline, hiệu chỉnh ngưỡng trên validation và giữ test cuối độc lập.','2.5','0.25','["baseline", "ngưỡng", "validation"]','["So sánh baseline, hiệu chỉnh ngưỡng trên validation và giữ test cuối độc lập.", "Đo cải thiện với phương án đơn giản, chọn ngưỡng ở dev rồi đánh giá lại trên test chưa dùng."]','["Có thể điều chỉnh ngưỡng theo test nhiều lần rồi coi test vẫn độc lập."]');
